function syncAboutHeroSlogan(progress: number): void {
  const top = document.querySelector<HTMLElement>(ABOUT_HERO_SLOGAN_TOP_SELECTOR);
  if (!top) return;

  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(ABOUT_HERO_SLOGAN_TEXT_SELECTOR),
  );
  const shouldShow =
    progress >= ABOUT_HERO_SLOGAN_REVEAL_START &&
    progress < ABOUT_HERO_SLOGAN_REVEAL_END;

  if (aboutSceneDomState.isHeroSloganVisible === shouldShow) return;
  aboutSceneDomState.isHeroSloganVisible = shouldShow;
  aboutSceneDomState.heroSloganTimers = clearTimers(
    aboutSceneDomState.heroSloganTimers,
  );

  if (shouldShow) {
    BlockReveal.reveal(top);
    TextReveal.setVisibleOff(textItems);
    textItems.forEach((item, index) => {
      const timerId = window.setTimeout(() => {
        TextReveal.setVisibleOn(item);
      }, index * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
      aboutSceneDomState.heroSloganTimers.push(timerId);
    });
    return;
  }

  textItems
    .slice()
    .reverse()
    .forEach((item, index) => {
      const timerId = window.setTimeout(() => {
        TextReveal.setVisibleOff(item);
      }, index * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
      aboutSceneDomState.heroSloganTimers.push(timerId);
    });

  const hideTimerId = window.setTimeout(() => {
    BlockReveal.hide(top);
  }, textItems.length * ABOUT_HERO_SLOGAN_REVEAL_STAGGER_SECONDS * 1000);
  aboutSceneDomState.heroSloganTimers.push(hideTimerId);
}

function disposeAboutHeroSlogan(): void {
  aboutSceneDomState.isHeroSloganVisible = false;
  aboutSceneDomState.heroSloganTimers = clearTimers(
    aboutSceneDomState.heroSloganTimers,
  );

  const top = document.querySelector<HTMLElement>(ABOUT_HERO_SLOGAN_TOP_SELECTOR);
  if (!top) return;
  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(ABOUT_HERO_SLOGAN_TEXT_SELECTOR),
  );
  textItems.forEach((item) => TextReveal.setVisibleOff(item));
  BlockReveal.hide(top);
}

